mkdir -p /home/eval/recon/out && cat > /home/eval/recon/recon.awk <<'EOF'
function parse(line, f,    n, i, c, inq, cur) {
  n = 0; cur = ""; inq = 0
  for (i = 1; i <= length(line); i++) {
    c = substr(line, i, 1)
    if (inq) {
      if (c == "\"") {
        if (substr(line, i + 1, 1) == "\"") { cur = cur "\""; i++ } else inq = 0
      } else cur = cur c
    } else if (c == "\"") inq = 1
    else if (c == ",") { f[++n] = cur; cur = "" }
    else cur = cur c
  }
  f[++n] = cur
  return n
}
function cents(s,    p, n, w, fr) {
  gsub(/[ ,]/, "", s)
  n = split(s, p, ".")
  w = p[1]; fr = (n > 1) ? p[2] : ""
  fr = substr(fr "000", 1, 3)
  if (substr(fr, 3, 1) != "0") { print "sub-cent amount: " s > "/dev/stderr"; exit 2 }
  return w * 100 + substr(fr, 1, 2)
}
function money(c) { return sprintf("%d.%02d", int(c / 100), c % 100) }
function sortids(arr, n,    i, j, t) {
  for (i = 2; i <= n; i++) { t = arr[i]; for (j = i - 1; j >= 1 && arr[j] > t; j--) arr[j + 1] = arr[j]; arr[j + 1] = t }
}
FNR == 1 { next }
FILENAME ~ /ledger/ {
  parse($0, f)
  ld[f[1]] = f[2]; la[f[1]] = cents(f[4]); lt += la[f[1]]; nl++
  next
}
{
  split($0, b, "\t")
  ref = toupper(b[1]); gsub(/^ +| +$/, "", ref)
  split(b[2], d, "/"); date = d[3] "-" d[2] "-" d[1]
  amt = cents(b[4])
  key = ref SUBSEP date SUBSEP amt
  if (key in seen) { dup++; next }
  seen[key] = 1
  bd[ref] = date; ba[ref] = amt; bt += amt; nb++
}
END {
  for (id in ld) ids[++ni] = id
  sortids(ids, ni)
  for (id in bd) bids[++nbi] = id
  sortids(bids, nbi)
  for (i = 1; i <= ni; i++) {
    id = ids[i]
    if (!(id in bd)) { mb[++nmb] = id; continue }
    if (la[id] == ba[id] && ld[id] == bd[id]) matched++
    if (la[id] != ba[id]) am[++nam] = "  " id " ledger=" money(la[id]) " bank=" money(ba[id])
    if (ld[id] != bd[id]) dm[++ndm] = "  " id " ledger=" ld[id] " bank=" bd[id]
  }
  for (i = 1; i <= nbi; i++) if (!(bids[i] in ld)) ml[++nml] = "  " bids[i]
  printf "ledger_rows: %d\nbank_rows: %d\nduplicate_bank_rows: %d\n", nl, nb, dup
  printf "ledger_total: %s\nbank_total: %s\nmatched: %d\n", money(lt), money(bt), matched
  print "amount_mismatch: " nam + 0; for (i = 1; i <= nam; i++) print am[i]
  print "date_mismatch: " ndm + 0; for (i = 1; i <= ndm; i++) print dm[i]
  print "missing_in_bank: " nmb + 0; for (i = 1; i <= nmb; i++) print "  " mb[i]
  print "missing_in_ledger: " nml + 0; for (i = 1; i <= nml; i++) print ml[i]
}
EOF
