mkdir -p /home/eval/pkgs/bin /home/eval/pkgs/build && cat > /home/eval/pkgs/bin/order.awk <<'EOF'
{ sub(/#.*/, "") }
!/:/ { next }
{
  p = $0; sub(/:.*/, "", p); gsub(/[ \t]/, "", p)
  if (p == "") next
  node[p] = 1
  d = $0; sub(/^[^:]*:/, "", d)
  n = split(d, ds, /[ \t]+/)
  for (i = 1; i <= n; i++) {
    if (ds[i] == "") continue
    node[ds[i]] = 1
    if (!((ds[i], p) in edge)) { edge[ds[i], p] = 1; indeg[p]++ }
  }
}
END {
  total = 0
  for (x in node) total++
  done = 0
  while (1) {
    best = ""
    for (x in node) if (!(x in out) && indeg[x] + 0 == 0 && (best == "" || x < best)) best = x
    if (best == "") break
    out[best] = 1; done++
    print best
    for (x in node) if ((best, x) in edge) indeg[x]--
  }
  if (done < total) {
    rest = ""
    while (1) {
      best = ""
      for (x in node) if (!(x in out) && (best == "" || x < best)) best = x
      if (best == "") break
      out[best] = 1
      rest = rest " " best
    }
    print "cycle:" rest > "/dev/stderr"
    exit 1
  }
}
EOF
